def rectplot(q,fn,a,b,cases,ylim=None,caption=None):
 a,b=float(a),float(b);samples=[float(fn(a+(b-a)*j/500))for j in range(501)];height=430*len(cases);out=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 660 {height}"><rect width="660" height="{height}" fill="white"/>'];ymax=(max(samples)*1.13 or 1)if ylim is None else ylim
