  for j in range(5):
   xx=a+(b-a)*j/4;yy=ymax*j/4;out.append(f'<text x="{X(xx)-12}" y="{off+373}" font-size="11">{xx:.4g}</text><text x="5" y="{Y(yy)+4}" font-size="10">{yy:.4g}</text>')
  out.append(f'<text x="60" y="{off+411}" font-size="12">Blue: approximating rectangles. Red: function or sample interpolant.</text>')
